-- Migration 011: ESSA email templates + invoice workbench filter columns.
-- Postgres (this app's runtime). Dedicated ESSA_INVOICE header linked to AP_DOCUMENT.
-- Schema only — no INSERT. Scenario catalog + templates are seeded separately
-- via db/seed-email-templates.ts (scenarios/variables only; no system templates).

CREATE TABLE IF NOT EXISTS "ESSA_EMAIL_SCENARIO" (
  "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "ScenarioKey" VARCHAR(80) NOT NULL,
  "Label" VARCHAR(120) NOT NULL,
  "Description" VARCHAR(500) NULL,
  "Category" VARCHAR(40) NOT NULL,
  "DefaultTo" VARCHAR(200) NOT NULL,
  "DefaultCc" VARCHAR(200) NULL,
  "DefaultBcc" VARCHAR(200) NULL,
  "IsDeleted" BOOLEAN NOT NULL DEFAULT FALSE,
  "CreatedDt" TIMESTAMP NOT NULL DEFAULT NOW(),
  "CreatedBy" INTEGER NULL,
  "ModifiedDt" TIMESTAMP NULL,
  "ModifiedBy" INTEGER NULL
);

CREATE UNIQUE INDEX IF NOT EXISTS "UX_ESSA_EMAIL_SCENARIO_ScenarioKey"
  ON "ESSA_EMAIL_SCENARIO" ("ScenarioKey");

CREATE TABLE IF NOT EXISTS "ESSA_EMAIL_SCENARIO_VARIABLE" (
  "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "ScenarioId" INTEGER NOT NULL REFERENCES "ESSA_EMAIL_SCENARIO" ("Id"),
  "VariableName" VARCHAR(80) NOT NULL,
  "Label" VARCHAR(120) NOT NULL,
  "SampleValue" VARCHAR(200) NULL,
  "IsRequired" BOOLEAN NOT NULL DEFAULT FALSE
);

CREATE UNIQUE INDEX IF NOT EXISTS "UX_ESSA_EMAIL_SCENARIO_VARIABLE_Name"
  ON "ESSA_EMAIL_SCENARIO_VARIABLE" ("ScenarioId", "VariableName");

CREATE TABLE IF NOT EXISTS "ESSA_EMAIL_TEMPLATE" (
  "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "Name" VARCHAR(200) NOT NULL,
  "ScenarioKey" VARCHAR(80) NOT NULL,
  "Description" VARCHAR(500) NULL,
  "Subject" VARCHAR(500) NOT NULL,
  "BodyHtml" TEXT NOT NULL,
  "RecipientTo" VARCHAR(500) NOT NULL,
  "RecipientCc" VARCHAR(500) NULL,
  "RecipientBcc" VARCHAR(500) NULL,
  "RequiredPlaceholders" VARCHAR(500) NOT NULL,
  "Status" VARCHAR(20) NOT NULL,
  "IsSystem" BOOLEAN NOT NULL DEFAULT FALSE,
  "Version" INTEGER NOT NULL DEFAULT 1,
  "IsDeleted" BOOLEAN NOT NULL DEFAULT FALSE,
  "CreatedDt" TIMESTAMP NOT NULL DEFAULT NOW(),
  "CreatedBy" INTEGER NULL,
  "ModifiedDt" TIMESTAMP NULL,
  "ModifiedBy" INTEGER NULL
);

CREATE INDEX IF NOT EXISTS "IX_ESSA_EMAIL_TEMPLATE_ScenarioKey"
  ON "ESSA_EMAIL_TEMPLATE" ("ScenarioKey", "Status", "IsDeleted");

CREATE TABLE IF NOT EXISTS "ESSA_EMAIL_TEMPLATE_VERSION" (
  "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "TemplateId" INTEGER NOT NULL,
  "Version" INTEGER NOT NULL,
  "Action" VARCHAR(20) NOT NULL,
  "SnapshotJson" TEXT NOT NULL,
  "Note" VARCHAR(300) NULL,
  "ChangedAt" TIMESTAMP NOT NULL DEFAULT NOW(),
  "ChangedBy" INTEGER NULL
);

CREATE INDEX IF NOT EXISTS "IX_ESSA_EMAIL_TEMPLATE_VERSION_Template"
  ON "ESSA_EMAIL_TEMPLATE_VERSION" ("TemplateId", "Version" DESC);

CREATE TABLE IF NOT EXISTS "ESSA_INVOICE" (
  "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "DocumentId" BIGINT NOT NULL,
  "InvoiceHeaderId" INTEGER NULL,
  "InvoiceNo" VARCHAR(50) NULL,
  "InvoiceDate" DATE NULL,
  "VendorName" VARCHAR(250) NULL,
  "VendorCode" VARCHAR(50) NULL,
  "PoNumber" VARCHAR(50) NULL,
  "InvoiceWorkflow" VARCHAR(10) NOT NULL,
  "InvoiceType" VARCHAR(40) NOT NULL,
  "WorkflowStage" VARCHAR(30) NOT NULL,
  "FailedChecks" INTEGER NOT NULL DEFAULT 0,
  "OpenExceptions" INTEGER NOT NULL DEFAULT 0,
  "SlaDueAt" TIMESTAMP NULL,
  "SlaBreached" BOOLEAN NOT NULL DEFAULT FALSE,
  "TotalAmount" DECIMAL(18,2) NULL,
  "Currency" VARCHAR(10) NOT NULL DEFAULT 'IDR',
  "IsDeleted" BOOLEAN NOT NULL DEFAULT FALSE,
  "CreatedDt" TIMESTAMP NOT NULL DEFAULT NOW(),
  "CreatedBy" INTEGER NULL,
  "ModifiedDt" TIMESTAMP NULL,
  "ModifiedBy" INTEGER NULL
);

CREATE UNIQUE INDEX IF NOT EXISTS "UX_ESSA_INVOICE_DocumentId"
  ON "ESSA_INVOICE" ("DocumentId");
CREATE INDEX IF NOT EXISTS "IX_ESSA_INVOICE_Filters"
  ON "ESSA_INVOICE" ("InvoiceWorkflow", "WorkflowStage", "InvoiceType", "InvoiceDate");
CREATE INDEX IF NOT EXISTS "IX_ESSA_INVOICE_SlaBreached"
  ON "ESSA_INVOICE" ("SlaBreached");
CREATE INDEX IF NOT EXISTS "IX_ESSA_INVOICE_FailedChecks"
  ON "ESSA_INVOICE" ("FailedChecks");
CREATE INDEX IF NOT EXISTS "IX_ESSA_INVOICE_InvoiceNo"
  ON "ESSA_INVOICE" ("InvoiceNo");
CREATE INDEX IF NOT EXISTS "IX_ESSA_INVOICE_PoNumber"
  ON "ESSA_INVOICE" ("PoNumber");
